css:
@page { margin: 20mm; }
/* Базові налаштування */
.print-format {
  font-family: "Times New Roman", Times, serif !important;
  font-size: 13pt !important;
  line-height: 1.1;
}
.print-format * {
  font-family: "Times New Roman", Times, serif !important;
  font-size: 13pt !important;
  line-height: inherit;
}

/* Шапка документа */
.print-format .header-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 16px;
  font-size: 13pt !important;
}
.print-format .header-table td {
  border: none;
  padding: 0;
  font-size: 13pt !important;
  vertical-align: top;
}
.print-format .header-table .header-left {
  width: 50%;
  text-align: left;
}
.print-format .header-table .header-right {
  width: 50%;
  text-align: left;
  padding-left: 20px;
}
.print-format .header-table * {
  font-size: 13pt !important;
}

/* Попередження про різні ціни */
.print-format .warning-box {
  background-color: #fff3cd;
  border: 2px solid #ff6b6b;
  padding: 10px;
  margin: 10px 0;
  border-radius: 4px;
  color: #856404;
  font-weight: 600;
}

/* Заголовок */
.print-format .title {
  text-align: center;
  margin: 6px 0;
}

/* Підзаголовок */
.print-format .subtitle-left {
  text-align: left;
  font-weight: 700;
  margin: 4px 0 12px;
}

/* Абзац */
.print-format .p {
  text-indent: 1.25cm;
  text-align: justify;
  margin: 8px 0;
}

/* Підпис таблиці */
.print-format .caption-right {
  text-align: right;
  font-weight: 600;
  margin: 10px 0 4px;
}

/* Основна таблиця */
.print-format table.print-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11pt !important;
  table-layout: auto;
}
.print-format table.print-table th,
.print-format table.print-table td {
  border: 1px solid #444;
  padding: 6px;
  vertical-align: top;
  font-size: 11pt !important;
}
.print-format table.print-table th {
  font-weight: 700;
  text-align: center;
}
.print-format table.print-table * {
  font-size: 11pt !important;
}

/* Ширини колонок */
.print-format table.print-table th:nth-child(1),
.print-format table.print-table td:nth-child(1) {
  width: 3%;
  white-space: nowrap;
}
.print-format table.print-table th:nth-child(2),
.print-format table.print-table td:nth-child(2) {
  
  white-space: normal;
}
.print-format table.print-table th:nth-child(3),
.print-format table.print-table td:nth-child(3) {
  width: 5%;
  white-space: nowrap;
}
.print-format table.print-table th:nth-child(4),
.print-format table.print-table td:nth-child(4) {
  width: 5%;
  white-space: nowrap;
}
.print-format table.print-table th:nth-child(5),
.print-format table.print-table td:nth-child(5) {
  width: 9%;
  white-space: nowrap;
}
.print-format table.print-table th:nth-child(6),
.print-format table.print-table td:nth-child(6) {
  width: 15%;
  white-space: nowrap;
}

/* Вирівнювання */
.print-format td.center { text-align: center; }
.print-format td.num, 
.print-format th.num { text-align: center; white-space: nowrap; }

/* Таблиця підпису */
.print-format .sign-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 24px;
  font-size: 14pt !important;
}
.print-format .sign-table td {
  border: none;
  padding: 10px;
  font-size: 14pt !important;
}
.print-format .sign-table .sign-left {
  width: 60%;
  text-align: left;
  vertical-align: top;
}
.print-format .sign-table .sign-right {
  width: 40%;
  text-align: right;
  vertical-align: bottom;
}
.print-format .sign-table * {
  font-size: 14pt !important;
}

html:
{%- set items = doc.items or [] -%}
{%- macro money(v) -%}
  {{- "{:,.2f}".format(v).replace(",", " ").replace(".", ",") if v is number else "-" -}}
{%- endmacro -%}
{%- set basis = (doc.decision and frappe.db.get_value("oiBasisDoc", doc.decision, ["reason","subject","description"], as_dict=True)) or {} -%}
{%- set basis_reason = basis.reason or basis.subject or basis.description or "Вихід з ладу у зв'язку з інтенсивною експлуатацією" -%}

{# Об'єднання активів за inventory_no + asset_name #}
{%- set merged_items = {} -%}
{%- set price_warnings = [] -%}
{%- for row in items -%}
  {%- set a = row.asset and frappe.db.get_value("oiAsset", row.asset, ["asset_name","inventory_no","serial_no","cost"], as_dict=True) or {} -%}
  {%- set asset_name = a.asset_name or row.asset or "-" -%}
  {%- set inv_no = row.inventory_no or a.inventory_no or "-" -%}
  {%- set key = (inv_no ~ "|" ~ asset_name) -%}
  
  {%- if key not in merged_items -%}
    {%- set _ = merged_items.update({key: {
      "asset_name": asset_name,
      "inventory_no": inv_no,
      "unit_price": row.unit_price if row.unit_price is not none else a.cost,
      "count": row.count or 1,
      "total": row.total or 0,
      "reason": row.reason or basis_reason,
      "serial_nos": [row.serial_no] if row.serial_no else []
    }}) -%}
  {%- else -%}
    {%- set existing = merged_items[key] -%}
    {%- set current_price = row.unit_price if row.unit_price is not none else a.cost -%}
    {%- if existing.unit_price != current_price -%}
      {%- set _ = price_warnings.append("УВАГА: Різні ціни для '" ~ asset_name ~ "' (інв. № " ~ inv_no ~ "): " ~ money(existing.unit_price) ~ " та " ~ money(current_price)) -%}
    {%- endif -%}
    {%- set _ = existing.update({"count": existing.count + (row.count or 1)}) -%}
    {%- set _ = existing.update({"total": existing.total + (row.total or 0)}) -%}
    {%- if row.serial_no -%}
      {%- set _ = existing.serial_nos.append(row.serial_no) -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}

<table class="header-table">
  <tr>
    <td class="header-left">
      {%- if doc.registration_index -%}
        № {{ doc.registration_index }}
      {%- endif -%}
      {%- if doc.registration_date -%}
        {%- if doc.registration_index %} від {% endif -%}
        {{ frappe.utils.formatdate(doc.registration_date, "dd.MM.yyyy") }}
      {%- endif -%}
    </td>
    <td class="header-right">
      <div>Першому заступнику міського голови</div>
      <div>з питань діяльності виконавчих органів ради</div>
      <div>Ірині РУДАКОВІЙ</div>
    </td>
  </tr>
</table>

{%- if price_warnings -%}
<div class="warning-box">
  {%- for warning in price_warnings -%}
    <div>⚠️ {{ warning }}</div>
  {%- endfor -%}
</div>
{%- endif -%}

<div class="title">СЛУЖБОВА ЗАПИСКА</div>

<div class="subtitle-left">
Щодо списання<br/>матеріальних цінностей
</div>

<div class="p">
У зв'язку з інтенсивною експлуатацією та великим навантаженням прошу розглянути можливість списання наступних матеріальних цінностей згідно Таблиці 1.
</div>

<div class="caption-right">Таблиця 1. Список матеріальних цінностей</div>

<table class="print-table">
  <thead>
    <tr>
      <th class="center">№</th>
      <th>Найменування<br/>матеріальних<br/>цінностей</th>
      <th class="num">Ціна за<br/>одиницю</th>
      <th class="center">Кіл-ть</th>
      <th class="num">Сума,<br/>грн.</th>
      <th class="center">Інвентарний<br/>номер</th>
      <th>Причина списання</th>
    </tr>
  </thead>
  <tbody>
    {%- for i, (key, row) in enumerate(merged_items.items(), start=1) -%}
      {%- set serial_display = row.serial_nos | join(", ") if row.serial_nos else "" -%}
      <tr>
        <td class="center">{{ i }}</td>
        <td>
          {{- row.asset_name -}}
          {%- if serial_display %}<br/><small>Серійний №: {{ serial_display }}</small>{% endif -%}
        </td>
        <td class="num">{{ money(row.unit_price) }}</td>
        <td class="center">{{ row.count }}</td>
        <td class="num">{{ money(row.total) }}</td>
        <td class="center">{{ row.inventory_no }}</td>
        <td>{{ row.reason }}</td>
      </tr>
    {%- endfor -%}
  </tbody>
   <tfoot>
    <tr>
      <th colspan="4" class="num">Разом:</th>
      <th class="num" colspan="3">{{ money(doc.total_amount) }}</td>
    </tr>
  </tfoot>
</table>

<table class="sign-table">
  <tr>
    <td class="sign-left">
      <div>В.о начальника, заступник начальника</div>
      <div>відділу інформаційних технологій</div>
      <div>та захисту інформації</div>
    </td>
    <td class="sign-right">Максим СИСОЄВ</td>
  </tr>
</table>
